/* Tiny offline interaction layer for navbar and accordion collapse. */
document.addEventListener('click',function(e){const t=e.target.closest('[data-bs-toggle="collapse"]');if(!t)return;const sel=t.getAttribute('data-bs-target');const el=document.querySelector(sel);if(!el)return;el.classList.toggle('show');t.classList.toggle('collapsed',!el.classList.contains('show'));});
